  private async migrateExisting(raw:IDBPDatabase<GenesisSchema>){const names=Array.from(raw.objectStoreNames).filter(name=>this.encrypted(name));for(const name of names){const values=await raw.getAll(name as any),keys=await raw.getAllKeys(name as any);const migrated:unknown[]=[];for(const value of values)migrated.push(await this.encryptValue(name,value));if(!migrated.some((value:any)=>value?.__auxoEncrypted))continue;const tx=raw.transaction(name as any,'readwrite'),store=tx.objectStore(name as any);for(let i=0;i<migrated.length;i++){const value=migrated[i] as any;if(value?.__auxoEncrypted){if(store.keyPath===null)await store.put(value,keys[i] as any);else await store.put(value);}}await tx.done;}}
  async initializeDatabaseEncryption(password:string):Promise<DatabaseKeyWrap>{const raw=await this.openRaw();let migration=await raw.get('appMeta','database-key-migration') as any,wrap=migration?.wrap as DatabaseKeyWrap|undefined;if(wrap){const key=await unwrapDatabaseKey(wrap,password);this.masterKey=await crypto.subtle.importKey('raw',key,{name:'AES-GCM'},true,['encrypt','decrypt']);}else{const bytes=crypto.getRandomValues(new Uint8Array(32));this.masterKey=await crypto.subtle.importKey('raw',bytes,{name:'AES-GCM'},true,['encrypt','decrypt']);wrap=await wrapDatabaseKey(bytes,password);await raw.put('appMeta',{wrap} as any,'database-key-migration');}this.encryptionEnabled=true;await this.migrateExisting(raw);return wrap!;}
