  async wrapDatabaseEncryptionKey(password:string):Promise<DatabaseKeyWrap>{if(!this.masterKey)throw new Error('The encrypted database is locked. Sign in first.');const raw=new Uint8Array(await crypto.subtle.exportKey('raw',this.masterKey));return wrapDatabaseKey(raw,password);}
  async exportDatabaseEncryptionKey(){if(!this.masterKey)throw new Error('The encrypted database is locked. Sign in first.');return new Uint8Array(await crypto.subtle.exportKey('raw',this.masterKey));}
  async installDatabaseEncryptionKey(raw:Uint8Array){if(raw.byteLength!==32)throw new Error('Encrypted backup database key is invalid.');this.masterKey=await crypto.subtle.importKey('raw',raw as BufferSource,{name:'AES-GCM'},true,['encrypt','decrypt']);this.encryptionEnabled=true;}
