  private indexPath(name:string,index:string){const paths:Record<string,Record<string,string>>={invoices:{'by-number':'number'},customerLedger:{'by-customer':'customerId'},accounts:{'by-identifier':'identifier'},heldBills:{'by-token':'tokenNumber','by-table':'tableNumber'},purchaseOrders:{'by-number':'number'},purchaseReceipts:{'by-number':'number'},dayClosings:{'by-date':'figures.date'},loyaltyLedger:{'by-customer':'customerId','by-invoice':'invoiceId','by-source-invoice':'sourceInvoiceId'},stockBatches:{'by-variant':'variantId','by-expiry':'expiryDate'},auditLog:{'by-created-at':'createdAt'},stockCounts:{'by-status':'status'},categories:{'by-sort':'sortOrder'},quotations:{'by-number':'number'}};return paths[name]?.[index]??index;}
