  private wrapDatabase(db:IDBPDatabase<GenesisSchema>){const self=this;return new Proxy(db,{get(target,property){if(property==='transaction')return (...args:any[])=>self.wrapTransaction((target.transaction as any)(...args),Array.isArray(args[0])?args[0]:[args[0]]);if(['get','getAll','getAllKeys','count','put','add','delete','clear'].includes(String(property)))return async(...args:any[])=>{const method=String(property),name=String(args[0]);if(!self.encrypted(name))return (target as any)[method](...args);if(method==='put'||method==='add'){const value=await self.encryptValue(name,args[1]);return (target as any)[method](args[0],value,...args.slice(2));}if(method==='get'){const value=await (target as any)[method](...args);return self.decryptValue(name,value);}if(method==='getAll'){const values=await (target as any)[method](...args);return Promise.all(values.map((value:any)=>self.decryptValue(name,value)));}return (target as any)[method](...args);};if(property==='getAllFromIndex'||property==='getFromIndex')return async(name:string,index:string,query?:IDBValidKey|IDBKeyRange,count?:number)=>{if(!self.encrypted(name))return (target as any)[property](name,index,query,count);const rows=await self.indexRows(name,index,query,count);return property==='getFromIndex'?rows[0]:rows;};const value=Reflect.get(target,property,target);return typeof value==='function'?value.bind(target):value;}}) as unknown as IDBPDatabase<GenesisSchema>;}
  async saveProductPhoto(id:string,blob:Blob){if(!id||blob.type!=='image/jpeg'||blob.size<1||blob.size>4*1024*1024)throw new Error('Product photo is invalid or exceeds 4 MB.');await (await this.connect()).put('productPhotos',{id,blob});}
  async getProductPhoto(id:string){return (await (await this.connect()).get('productPhotos',id))?.blob??null;}
  async cleanupUnusedProductPhotos(){const db=await this.connect(),tx=db.transaction(['products','productPhotos','shop'],'readwrite'),products=await tx.objectStore('products').getAll(),shop=await tx.objectStore('shop').get('identity'),photos=tx.objectStore('productPhotos'),all=await photos.getAll(),used=new Set([...products.flatMap(p=>[p.photoId??null,...p.variants.map(v=>v.photoId??null)]),shop?.storeLogoPhotoId??null].filter((id):id is string=>Boolean(id)));for(const photo of all)if(!used.has(photo.id))await photos.delete(photo.id);await tx.done;}
  async load(): Promise<ShopIdentity | null> {
    return (await (await this.connect()).get('shop', 'identity')) ?? null;
  }
  async save(shop: ShopIdentity,audit?:AuditWrite): Promise<void> {
    const db = await this.connect();
    const transaction = db.transaction(['shop','auditLog'], 'readwrite');
    await transaction.objectStore('shop').put(shop, 'identity');
    if(audit)await this.addAudit(transaction,audit);
    await transaction.done;
  }
  async recordAudit(actor:{id:string;name:string;role:'SUPER_ADMIN'|'EMPLOYEE'}|null,action:AuditAction,entityType:AuditEntity,entityId:string|null,summary:string,createdAt=Date.now()){const db=await this.connect();const tx=db.transaction('auditLog','readwrite');await tx.store.add({id:crypto.randomUUID(),createdAt,actorId:actor?.id??null,actorName:actor?.name??'Unknown',actorRole:actor?.role??null,action,entityType,entityId,summary:summary.slice(0,300)} satisfies AuditRecord);await tx.done;}
  private auditRow(write:AuditWrite):AuditRecord{return {id:crypto.randomUUID(),createdAt:write.createdAt??Date.now(),actorId:write.actor?.id??null,actorName:write.actor?.name??'Unknown',actorRole:write.actor?.role??null,action:write.action,entityType:write.entityType,entityId:write.entityId,summary:write.summary.slice(0,300)}}
  private async addAudit(tx:IDBPTransaction<GenesisSchema,any,'readwrite'>,write:AuditWrite){try{await tx.objectStore('auditLog').add(this.auditRow(write));}catch(error){try{await tx.done;}catch{/* Consume the transaction rejection after abort. */}throw error;}}
  async listRecentAudit(limit=300){return (await (await this.connect()).getAll('auditLog')).sort((a,b)=>b.createdAt-a.createdAt||b.id.localeCompare(a.id)).slice(0,Math.max(1,Math.min(1000,limit)));}
  async listCategories(){const db=await this.connect(),tx=db.transaction('categories','readwrite'),store=tx.objectStore('categories'),rows=await store.getAll();if(!rows.length){const seeded=(Object.keys(PRODUCT_CATEGORIES) as ProductCategory[]).map((profile,sortOrder):ShopCategory=>({id:profile,name:null,profile,enabled:!STARTS_OFF.has(profile),sortOrder,builtIn:true,subcategories:[]}));for(const row of seeded)await store.add(row);await tx.done;return seeded;}const normalized=rows.map(row=>({...row,subcategories:row.subcategories??[]}));for(let i=0;i<rows.length;i++)if(!rows[i]!.subcategories)await store.put(normalized[i]!);await tx.done;return normalized.sort((a,b)=>a.sortOrder-b.sortOrder||a.id.localeCompare(b.id));}
  async needsCategorySetup(){return !(await (await this.connect()).get('appMeta','categorySetupDone'));}
  async applyCategorySetup(enabledIds:Set<string>,actor:AuditWrite['actor']){await this.listCategories();const db=await this.connect(),tx=db.transaction(['categories','auditLog','appMeta'],'readwrite'),store=tx.objectStore('categories'),rows=await store.getAll();if(!rows.some(row=>enabledIds.has(row.id))){await tx.done;throw new Error('Choose at least one selling category.');}for(const row of rows)await store.put({...row,enabled:enabledIds.has(row.id)});await this.addAudit(tx,{actor,action:'CATEGORIES_CHANGED',entityType:'category',entityId:null,summary:'Categories chosen during setup'});await tx.objectStore('appMeta').put(true,'categorySetupDone');await tx.done;}
  async addCategory(name:string,profile:ProductCategory,actor:AuditWrite['actor']){const db=await this.connect(),tx=db.transaction(['categories','auditLog'],'readwrite'),store=tx.objectStore('categories'),rows=await store.getAll(),names=rows.map(row=>row.name??defaultCategoryName(row.profile)),check=checkCategoryName(name,names);if(!check.ok){await tx.done;throw new Error(check.message);}const row:ShopCategory={id:crypto.randomUUID(),name:check.name,profile,enabled:true,sortOrder:Math.max(-1,...rows.map(x=>x.sortOrder))+1,builtIn:false};await store.add(row);await this.addAudit(tx,{actor,action:'CATEGORIES_CHANGED',entityType:'category',entityId:row.id,summary:`Category "${row.name}" added`});await tx.done;return row;}
