    const photoIds=[product.photoId??null,...product.variants.map(v=>v.photoId??null)].filter((id):id is string=>Boolean(id));for(const id of new Set(photoIds))if(!await tx.objectStore('productPhotos').get(id)){await tx.done;throw new Error('A selected product photo is no longer available. Choose it again.');}
