    if(['PACKAGED_FOOD','BEVERAGE','PHARMACY','COSMETICS'].includes(product.category))for(const v of product.variants)if(v.stock>0)await tx.objectStore('stockBatches').add({id:crypto.randomUUID(),variantId:v.id,batchNumber:v.batchNumber??null,expiryDate:v.expiryDate??null,quantity:v.stock,receivedAt:product.createdAt,unitCostPaise:v.costPaise??null} satisfies StockBatch);
