    const saved={...product,id:current.id,createdAt:current.createdAt,updatedAt:Date.now(),stockUnit:current.stockUnit,tracksStock:product.tracksStock??current.tracksStock??true,available:product.category==='RESTAURANT'?(product.available??true):true,variants};
